    ("arizonarivet-injectedrivets-birkoflornubuk-S005689-eva-g_1", "arizonarivet-injectedrivets-birkoflornubuk-S005689-eva-g", "arizona-rivet-border-kids-birko-flor-nubuck-black", "Arizona Rivet Border Kids Birko-Flor Nubuck", "Arizona Rivet Kids", "Birkibuc", "Black", "1", 69.95, None, "Exclusive", "Girls", "Two-strap sandals", "Classic", "1032544/1032563", "1032563", "Our Kids' Arizona sandal, with extra personality. Smooth studs match their sandals back to yours for a you-and-me style moment. Designed for all-day play, its original contoured footbed supports growing feet while adjustable straps help create the perfect fit.", 0.0, 0, "kids", ["kids", "kids-girls-sandals", "style-arizona"], ["products/p-arizona-rivet-border-kids-birko-flor-nubuck-black-1-1.jpg", "products/p-arizona-rivet-border-kids-birko-flor-nubuck-black-1-2.jpg", "products/p-arizona-rivet-border-kids-birko-flor-nubuck-black-1-3.jpg"]),
